94	void GFXScreen::setBrightness(uint8_t lvl) {
95	  static uint8_t last_lvl = 255; // Initialize to impossible value
96	  
97	  // Only print if brightness level changes
98	  if (lvl != last_lvl) {
99	    Serial.printf("Setting brightness to: %d (was: %d)\n", lvl, last_lvl);
100	    last_lvl = lvl;
101	  }
102	
103	  // For M5Stack CoreS3, use M5.Lcd.setBrightness
104	  // Map 0-100 percentage range to 0-255 device brightness
105	  if (lvl > 100) lvl = 100;
106	  uint8_t mapped_brightness = (uint8_t)((lvl * 255) / 100);
107	  // Ensure small non-zero levels are still visible but low-power
108	  if (lvl > 0 && mapped_brightness < 12) {
109	    mapped_brightness = 12;
110	  }
111	  
112	  // Apply the brightness
113	  M5.Lcd.setBrightness(mapped_brightness);
114	  
115	  // Force update the display
116	  M5.Lcd.wakeup();
117	}
