#ifndef SENSOR_REPORTER_AGGREGATOR_HPP_
#define SENSOR_REPORTER_AGGREGATOR_HPP_

#include <vector>
#include <map>
#include "Handler.hpp"
#include "Supervisor.hpp"
#include "Worker.hpp"

/**
 * Some class that collects the data from the workers and passes it to the data handlers.
 * Can register
 * - workers (that retrieve data/worker_reports)
 * - handlers (handle the work that the workers produced)
 * - supervisors (that handle the full report)
 */
class Aggregator {
 public:
  Aggregator();
  virtual ~Aggregator() = default;

  /**
   * Add a new worker to the aggregator
   * @param worker
   */
  void register_worker(uint8_t worker_id, BaseWorker& worker);

  /**
   * Add a new data handler to the aggregator
   * @param data handler
   */
  void register_handler(uint8_t handler_id, Handler& handler);

  /**
   * Add a new report supervisor to the aggregator, will be automatically activated
   * @param supervisor
   */
  void register_supervisor(Supervisor& supervisor);

  /**
   * Set the active status of a worker
   * @param worker_id
   * @param active
   */
  void set_worker_active(uint8_t worker_id, bool active);

  /**
   * Add a new data handler to the aggregator
   * @param worker_id
   * @param active
   */
  void set_handler_active(uint8_t handler_id, bool active);

  /**
   * Run the aggregator
   * Three steps:
   * 1. workers produce work
   *   - If no fresh work is produced, the next steps are skipped
   * 2. handlers handle produced work
   * 3. supervisor oversees final report
   */
  void run();

 private:
  WorkerMap workers;
  HandlerMap handlers;
  std::vector<Supervisor*> supervisors;

};

#endif //SENSOR_REPORTER_AGGREGATOR_HPP_

//
// Created by Jelle Bouwhuis on 12/24/19.
//

#include <Aggregator.hpp>

Aggregator::Aggregator() = default;

void Aggregator::register_worker(uint8_t worker_id, BaseWorker& worker) {
  if(workers.find(worker_id) == workers.end()) {
    // Create new worker and measurement
    workers[worker_id] = &worker;
    worker.initialize();
  } else {
    // Receiver with this id already exists...
    // TODO: add error logging
  }
}

void Aggregator::register_handler(uint8_t handler_id, Handler& handler) {
  if(handlers.find(handler_id) == handlers.end()) {
    // Create new handler
    handlers[handler_id] = &handler;
    handler.initialize();
  } else {
    // Observer with this id already exists...
    // TODO: add error logging
  }
}

void Aggregator::register_supervisor(Supervisor& supervisor) {
  supervisors.push_back(&supervisor);
  supervisor.initialize();
}

void Aggregator::run() {
  bool any_new = false;
  // Workers produce data
  for(const auto& w : workers) {
    auto& worker = w.second;
    if(worker && !worker->is_process_worker() && worker->work(workers)) {
      any_new = true;
    }
  }
  for(const auto& w : workers) {
    // Process workers produce data using the workers
    auto& worker = w.second;
    if(worker && worker->is_process_worker() && worker->work(workers)) {
      any_new = true;
    }
  }
  // Handlers handle produced work
  for(const auto& r : handlers) {
    auto handler = r.second;
    if(handler && (any_new || handler->get_status() == Handler::e_handler_processing)) {
      handler->try_handle_work(workers);
    }
  }
  // Submit final report
  for(const auto& report_handler : supervisors) {
    if(report_handler) {
      report_handler->handle_report(workers, handlers);
    }
  }

}

void Aggregator::set_worker_active(uint8_t worker_id, bool active) {
  workers.at(worker_id)->set_active(active);
}

void Aggregator::set_handler_active(uint8_t handler_id, bool active) {
  handlers.at(handler_id)->set_active(active);
}

